#!/usr/bin/env node
// Generates one React component per Phosphor icon (all 6 weights) into src/phosphor/generated,
// from the assets vendored by `yarn phosphor:sync`.
//
// Usage: yarn phosphor:generate [--check]
//   --check   do not write; exit 1 if the generated files are out of date (used by CI)

const fs = require('fs')
const path = require('path')

const {
  ROOT,
  WEIGHTS,
  componentName,
  readCatalog,
  readVersion,
  readIconShapes,
  writeFile,
  removeDir,
} = require('./shared')

const OUT_DIR = path.join(ROOT, 'src', 'phosphor', 'generated')
const check = process.argv.includes('--check')

function shapeLiteral(shape) {
  return typeof shape === 'string' ? `'${shape}'` : `['${shape[0]}', ${shape[1]}]`
}

function componentSource(entry, shapes, version) {
  const name = componentName(entry)
  const weights = WEIGHTS.map((weight) => `  ${weight}: [${shapes[weight].map(shapeLiteral).join(', ')}],`).join('\n')

  return `// Generated by tools/phosphor/generate.js — do not edit.
// Phosphor Icons ${version} · ${entry.name} · MIT License (see vendor/phosphor/LICENSE)
import { createPhosphorIcon } from '../createPhosphorIcon'

export const ${name} = createPhosphorIcon('${name}', {
${weights}
})
`
}

function indexSource(catalog, version) {
  const lines = [
    '// Generated by tools/phosphor/generate.js — do not edit.',
    `// Phosphor Icons ${version} · ${catalog.length} icons · MIT License (see vendor/phosphor/LICENSE)`,
  ]
  for (const entry of catalog) {
    lines.push(`export { ${componentName(entry)} } from './${componentName(entry)}'`)
  }

  const aliases = catalog.filter((entry) => entry.alias)
  if (aliases.length) {
    lines.push('')
    lines.push('// Deprecated names kept by Phosphor for backwards compatibility.')
    for (const entry of aliases) {
      lines.push(`export { ${componentName(entry)} as Ph${entry.alias.pascal_name} } from './${componentName(entry)}'`)
    }
  }
  return lines.join('\n') + '\n'
}

function namesSource(catalog, version) {
  const names = catalog.map((entry) => `  | '${componentName(entry)}'`).join('\n')
  return `// Generated by tools/phosphor/generate.js — do not edit.
// Phosphor Icons ${version} · ${catalog.length} icons

/** Names of every Phosphor icon component exported by \`@lemonade/ui/phosphor\`. */
export type PhosphorIconName =
${names}

export const PHOSPHOR_VERSION = '${version}'

export const PHOSPHOR_ICON_COUNT = ${catalog.length}
`
}

function main() {
  const catalog = readCatalog()
  const versionInfo = readVersion()
  const version = versionInfo ? versionInfo.version : 'unknown'

  const files = new Map()
  for (const entry of catalog) {
    files.set(`${componentName(entry)}.ts`, componentSource(entry, readIconShapes(entry), version))
  }
  files.set('index.ts', indexSource(catalog, version))
  files.set('names.ts', namesSource(catalog, version))

  if (check) {
    const existing = fs.existsSync(OUT_DIR) ? fs.readdirSync(OUT_DIR) : []
    const stale = []
    for (const [file, content] of files) {
      const target = path.join(OUT_DIR, file)
      if (!fs.existsSync(target) || fs.readFileSync(target, 'utf8') !== content) stale.push(file)
    }
    const extra = existing.filter((file) => !files.has(file))
    if (stale.length || extra.length) {
      console.error(`✗ src/phosphor/generated is out of date (${stale.length} changed, ${extra.length} extra).`)
      console.error('  Run "yarn phosphor:generate" and commit the result.')
      process.exit(1)
    }
    console.log(`✓ src/phosphor/generated is up to date (${catalog.length} icons, Phosphor ${version})`)
    return
  }

  removeDir(OUT_DIR)
  for (const [file, content] of files) {
    writeFile(path.join(OUT_DIR, file), content)
  }
  console.log(`✓ Generated ${catalog.length} icon components (6 weights each) in ${path.relative(ROOT, OUT_DIR)}`)
}

main()
